    # max_idx: max index for f (like 300)
    # max_sum: max sum of f (like 300)
    # f defined on 0..max_idx, decreasing, sum <= max_sum
    best = 0
    # Generate all decreasing sequences length max_idx+1 with sum <= max_sum
    # This is huge for 300, but for small we can brute force
    # For now, just for small exploration
